-- SplitMate demo seed: 50 users + groups/expenses/friends/settlements.
-- All demo users share password "demo1234".
-- Idempotent (deterministic ids + INSERT OR IGNORE).
--
-- DEVELOPMENT ONLY - this is not a migration, so it is never applied to the
-- production database. Apply it to a local database with:
--   npx wrangler d1 execute splitmate-db --local --file=./seed/demo_seed.sql


-- 50 demo users. All share password "demo1234".
WITH RECURSIVE cnt(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM cnt WHERE n < 50
),
pw(h) AS ( SELECT 'pbkdf2' || char(36) || '100000' || char(36) || 'RLVY01sz9y7-_egFQL0VeA' || char(36) || '2xn41QAo50j4-53_sPKQD3w0qElLebV4wIPhwFx7daU' )
INSERT OR IGNORE INTO users (id, email, password_hash, name, avatar_bg, created_at, updated_at)
SELECT
  'demo-' || substr('000' || n, -3),
  'demo' || substr('000' || n, -3) || '@splitmate.app',
  pw.h,
  'Demo User ' || n,
  CASE (n - 1) % 4 WHEN 0 THEN 'bg-primary-container' WHEN 1 THEN 'bg-secondary-container' WHEN 2 THEN 'bg-tertiary-container' ELSE 'bg-error-container' END,
  datetime('now', '-' || n || ' days'),
  datetime('now', '-' || n || ' days')
FROM cnt, pw;

